script:
(function () {
  'use strict';
  // Mortgage discount points: is paying points up front worth the lower rate?
  //   Cost of points = points / 100 * loan. Payments: M = L * i / (1 - (1 + i)^-n), i = rate / 12
  //   (M = L / n at 0%). Simple break-even = cost / monthly saving.
  //   Full break-even: net gain after month m = savings to date + (balance without points - balance
  //   with points) - cost, i.e. it also counts the faster principal paydown at the lower rate.
  //   With an optional return j (annual / 12 per month) the savings are compounded at j and the cost is
  //   grown at j, so the points must beat what the cash could have earned elsewhere.
  // Verified in Node (scratchpad tests/w2b): $300,000 for 30 yrs at 6.75% = $1,945.79/mo vs 6.375%
  //   = $1,871.61/mo; 1.5 points = $4,500, saving $74.18/mo, simple break-even 60.66 -> 61 months;
  //   full break-even month 48 and net gain $6,779.30 after 120 months, both matching closed-form
  //   balances B(1+i)^k - M((1+i)^k - 1)/i; lifetime $26,706.45 interest saved - $4,500; $200,000 at
  //   4.25% vs 4.00% = $983.88 vs $954.83; rate with points not lower = Never; no NaN/Infinity on
  //   blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(principal, annualPct, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function compare(loan, months, rate, ratePts, cost, annualReturn) {
    var pay = payment(loan, rate, months), payPts = payment(loan, ratePts, months);
    var j = annualReturn / 1200, b = loan, bp = loan, saved = 0, growth = 1, rows = [], breakeven = 0;
    var interest = 0, interestPts = 0;
    for (var m = 1; m <= months; m++) {
      var ia = b * rate / 1200, ib = bp * ratePts / 1200;
      interest += ia; interestPts += ib;
      b = m === months ? 0 : Math.max(0, b - (pay - ia));
      bp = m === months ? 0 : Math.max(0, bp - (payPts - ib));
      saved = saved * (1 + j) + (pay - payPts);
      growth *= 1 + j;
      var net = saved + (b - bp) - cost * growth;
      if (!breakeven && net >= 0) breakeven = m;
      rows.push({ n: m, saved: saved, equity: b - bp, net: net });
    }
    return { pay: pay, payPts: payPts, interest: interest, interestPts: interestPts, breakeven: breakeven, rows: rows };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearResults() {
    ['dpBreakeven', 'dpCost', 'dpMonthlySave', 'dpNet', 'dpPay', 'dpPayPts', 'dpSimpleBe', 'dpInt', 'dpIntPts',
     'dpLifeNet'].forEach(function (id) { setText(id, '–'); });
    setText('dpNote', '');
    el('dpSchedule').innerHTML = '';
  }

  function update() {
    var loan = read('dpLoan'), years = read('dpTerm'), rate = read('dpRate'), ratePts = read('dpRatePts'),
        points = read('dpPoints'), keep = read('dpYears'), ret = read('dpReturn', true);
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(years) || years < 1 || years > 40 || years % 1 !== 0) msg = 'Enter a loan term of 1 to 40 whole years.';
    else if (isNaN(rate) || rate < 0 || rate > 30 || isNaN(ratePts) || ratePts < 0 || ratePts > 30) msg = 'Enter interest rates from 0% to 30%.';
    else if (isNaN(points) || points < 0 || points > 10) msg = 'Enter from 0 to 10 points.';
    else if (isNaN(keep) || keep < 1 || keep % 1 !== 0 || keep > years) msg = 'Enter how many whole years you expect to keep the loan, up to the loan term.';
    else if (isNaN(ret) || ret < 0 || ret > 30) msg = 'Enter a return on cash from 0% to 30%.';
    var error = el('dpError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var months = years * 12, cost = loan * points / 100;
    var r = compare(loan, months, rate, ratePts, cost, ret);
    var monthlySave = r.pay - r.payPts;
    var atKeep = r.rows[keep * 12 - 1];

    setText('dpCost', money.format(cost));
    setText('dpMonthlySave', money.format(monthlySave));
    setText('dpPay', money.format(r.pay));
    setText('dpPayPts', money.format(r.payPts));
    setText('dpBreakeven', cost === 0 ? 'Immediately' : r.breakeven ? duration(r.breakeven) : 'Never');
    setText('dpSimpleBe', cost === 0 ? 'Immediately' : monthlySave > 0.005 && cost / monthlySave <= months ? duration(Math.ceil(cost / monthlySave)) : 'Never');
    setText('dpNet', money.format(atKeep.net));
    setText('dpInt', money.format(r.interest));
    setText('dpIntPts', money.format(r.interestPts));
    setText('dpLifeNet', money.format(r.interest - r.interestPts - cost));

    var note;
    if (ratePts >= rate && points > 0) note = 'The rate with points is not lower, so paying points does not save money.';
    else if (atKeep.net >= 0) note = 'Over ' + keep + (keep === 1 ? ' year' : ' years') + ' the points pay for themselves' + (ret > 0 ? ', even after what the cash could have earned.' : '.');
    else note = 'If you sell or refinance within ' + keep + (keep === 1 ? ' year' : ' years') + ', the points cost more than they save.';
    setText('dpNote', note);

    var html = [];
    for (var y = 1; y <= years; y++) {
      var row = r.rows[y * 12 - 1];
      html.push('<tr><td>' + y + '</td><td>' + money.format(row.saved) + '</td><td>' + money.format(row.equity) + '</td><td>' +
        money.format(row.net) + '</td></tr>');
    }
    el('dpSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dpForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
